import{c as e,i as t,o as n,r,s as i,t as a}from"./app-CSY-Kgjv.js";var o=JSON.parse(`{"path":"/web3/wallet/hd.html","title":"HD 钱包","lang":"zh-CN","frontmatter":{"description":"HD 钱包 HD 钱包（Hierarchical Deterministic Wallet，分层确定性钱包）是一种加密货币钱包，它通过一个根种子（通常由助记词生成）生成一系列的公钥和私钥。它的主要特性是可以通过单一的种子生成整个密钥对层次结构，且所有的密钥都可以被轻松恢复。 m / purpose' / coin_type' / account' / ...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"HD 钱包\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-03-11T05:49:26.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"DeeLMind\\",\\"url\\":\\"https://deelmind.com\\"}]}"],["meta",{"property":"og:url","content":"https://deelmind.com/web3/wallet/hd.html"}],["meta",{"property":"og:site_name","content":"極客方舟"}],["meta",{"property":"og:title","content":"HD 钱包"}],["meta",{"property":"og:description","content":"HD 钱包 HD 钱包（Hierarchical Deterministic Wallet，分层确定性钱包）是一种加密货币钱包，它通过一个根种子（通常由助记词生成）生成一系列的公钥和私钥。它的主要特性是可以通过单一的种子生成整个密钥对层次结构，且所有的密钥都可以被轻松恢复。 m / purpose' / coin_type' / account' / ..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-03-11T05:49:26.000Z"}],["meta",{"property":"article:modified_time","content":"2026-03-11T05:49:26.000Z"}]]},"git":{"createdTime":1734955114000,"updatedTime":1773208166000,"contributors":[{"name":"DeeLMind","username":"DeeLMind","email":"deelmind@gmail.com","commits":2,"url":"https://github.com/DeeLMind"}]},"readingTime":{"minutes":1.68,"words":503},"filePathRelative":"web3/wallet/hd.md","autoDesc":true}`),s={name:`hd.md`};function c(a,o,s,c,l,u){let d=e(`DocsAD`);return i(),r(`div`,null,[o[0]||=t(`<h1 id="hd-钱包" tabindex="-1"><a class="header-anchor" href="#hd-钱包"><span>HD 钱包</span></a></h1><p>HD 钱包（Hierarchical Deterministic Wallet，分层确定性钱包）是一种加密货币钱包，它通过一个根种子（通常由助记词生成）生成一系列的公钥和私钥。它的主要特性是可以通过单一的种子生成整个密钥对层次结构，且所有的密钥都可以被轻松恢复。</p><p><code>m / purpose&#39; / coin_type&#39; / account&#39; / change / address_index</code></p><p><code>m/44&#39;/0&#39;/0&#39;/0/0</code></p><ul><li><strong>purpose</strong>：表示使用的规范，如 BIP44 为 <code>44&#39;</code>。</li><li><strong>coin_type</strong>：代表加密货币的类型（例如，比特币是 <code>0&#39;</code>，以太坊是 <code>60&#39;</code>）。</li><li><strong>account</strong>：账户编号。</li><li><strong>change</strong>：<code>0</code> 表示外部地址（接收地址），<code>1</code> 表示内部地址（找零地址）。</li><li><strong>address_index</strong>：实际生成的地址索引。</li></ul><table><thead><tr><th>区块链</th><th>BIP-44 路径</th><th><code>coin_type</code></th></tr></thead><tbody><tr><td><strong>Bitcoin</strong></td><td><code>m/44&#39;/0&#39;/0&#39;/0/0</code></td><td><code>0</code></td></tr><tr><td><strong>Ethereum</strong></td><td><code>m/44&#39;/60&#39;/0&#39;/0/0</code></td><td><code>60</code></td></tr><tr><td><strong>Solana</strong></td><td><code>m/44&#39;/501&#39;/0&#39;/0&#39;</code></td><td><code>501</code></td></tr><tr><td><strong>Binance Coin (BNB)</strong></td><td><code>m/44&#39;/714&#39;/0&#39;/0/0</code></td><td><code>714</code></td></tr><tr><td><strong>Ripple (XRP)</strong></td><td><code>m/44&#39;/144&#39;/0&#39;/0/0</code></td><td><code>144</code></td></tr><tr><td><strong>Polkadot</strong></td><td><code>m/44&#39;/354&#39;/0&#39;/0/0</code></td><td><code>354</code></td></tr><tr><td><strong>Cosmos</strong></td><td><code>m/44&#39;/118&#39;/0&#39;/0/0</code></td><td><code>118</code></td></tr><tr><td><strong>Tezos</strong></td><td><code>m/44&#39;/1729&#39;/0&#39;/0/0</code></td><td><code>1729</code></td></tr><tr><td><strong>Litecoin</strong></td><td><code>m/44&#39;/2&#39;/0&#39;/0/0</code></td><td><code>2</code></td></tr><tr><td><strong>Cardano</strong></td><td><code>m/44&#39;/1815&#39;/0&#39;/0/0</code></td><td><code>1815</code></td></tr></tbody></table>`,6),n(d),o[1]||=t(`<h2 id="优缺点" tabindex="-1"><a class="header-anchor" href="#优缺点"><span>优缺点</span></a></h2><ul><li>备份简单：由于所有密钥对都来源于一个种子，用户只需要备份助记词，就能恢复所有地址和密钥。</li><li>增强隐私：HD 钱包可以为每个交易生成新的地址，提高用户隐私性。</li><li>多账户管理：通过分层结构，用户可以轻松管理多个账户和地址。</li><li>集中化风险：如果根种子泄露，攻击者可以推导出钱包的所有密钥对，从而窃取所有资产。</li></ul><h2 id="bip" tabindex="-1"><a class="header-anchor" href="#bip"><span>BIP</span></a></h2><p>BIP（Bitcoin Improvement Proposal，比特币改进提案）是为改进比特币协议或其相关软件提出的标准化流程。</p><ul><li>BIP32：HD（Hierarchical Deterministic）钱包的标准，用于定义分层确定性钱包的生成方式。</li><li>BIP39：助记词标准，用于生成钱包的助记词，并通过助记词恢复私钥。</li><li>BIP44：用于描述 HD 钱包的路径标准，用于确定不同加密货币和账户的密钥推导路径。</li></ul>`,5)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};